#include <libavcodec/avcodec.h>
#include <libavutil/pixfmt.h>

// Function to initialize the FFmpeg video decode engine
void FFmpegVideoDecodeEngine_Initialize(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig* config) {
    // Allocate codec context
    AVCodecContext* codec_ctx = avcodec_alloc_context3(NULL);
    if (!codec_ctx) {
        // Handle allocation failure
        return;
    }

    // Configure codec context based on the provided config
    codec_ctx->thread_count = 4; // Default to 4 threads
    codec_ctx->flags |= AV_CODEC_FLAG_LOW_DELAY;

    // Set pixel format and other codec-specific parameters
    codec_ctx->pix_fmt = AV_PIX_FMT_YUV420P;

    // Initialize buffer pool for output frames
    int buffer_pool_size = 10; // Default buffer pool size
    if (config->buffer_pool_size > 0 && config->buffer_pool_size < 100) {
        buffer_pool_size = config->buffer_pool_size;
    }

    // Validate buffer pool size to avoid excessive memory allocation
    if (buffer_pool_size > 100) {
        buffer_pool_size = 100;
    }

    // Initialize codec
    AVCodec* codec = avcodec_find_decoder(codec_ctx->codec_id);
    if (!codec) {
        avcodec_free_context(&codec_ctx);
        return;
    }

    if (avcodec_open2(codec_ctx, codec, NULL) < 0) {
        avcodec_free_context(&codec_ctx);
        return;
    }

    // Store the codec context in the provided context
    context->codec_context = codec_ctx;

    // Notify event handler upon completion
    if (event_handler && event_handler->on_initialized) {
        event_handler->on_initialized(message_loop, context);
    }
}
